package br.com.gestao.finance; import br.com.gestao.finance.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/finance") @PreAuthorize("hasRole('ADMIN')") public class FinancialController{private final FinancialEntryRepository repo;public FinancialController(FinancialEntryRepository r){repo=r;} @GetMapping public List<FinancialEntry> list(){return repo.findAllByOrderByCreatedAtDesc();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public FinancialEntry create(@Valid @RequestBody FinancialEntryRequest q,Authentication a){return repo.save(new FinancialEntry(null,q.type(),q.category(),q.description(),q.amount(),q.dueDate(),q.paid()!=null&&q.paid(),LocalDateTime.now(),a.getName()));} @PutMapping("/{id}") public FinancialEntry update(@PathVariable Long id,@Valid @RequestBody FinancialEntryRequest q){FinancialEntry e=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Lançamento não encontrado"));e.setType(q.type());e.setCategory(q.category());e.setDescription(q.description());e.setAmount(q.amount());e.setDueDate(q.dueDate());if(q.paid()!=null)e.setPaid(q.paid());return repo.save(e);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.deleteById(id);}}
